    10	/** Keep the mutation receipt before flushing: retry a failed write without editing twice. */
    11	export class DiagramRevisionReceiver {
    12	  private receipts = new Map<string, Receipt>();
    13	  async apply(documentId: string, input: DiagramRevisionApplication, controller: MappingDocumentController, persist: () => Promise<void>) {
    14	    return this.batch(documentId, { requestId: input.requestId, expectedVersion: input.expectedVersion, edits: [input], creations: [] }, controller, persist);
    15	  }
    16	  async batch(documentId: string, input: DiagramBatchApplication, controller: MappingDocumentController, persist: () => Promise<void>) {
    17	    const key = JSON.stringify([documentId, input.requestId]), signature = JSON.stringify(input);
    18	    let receipt = this.receipts.get(key);
    19	    if (receipt && receipt.signature !== signature) throw Error('REQUEST_ID_CONFLICT: revision application differs');
    20	    if (!receipt) {
    21	      if (this.receipts.size >= 2000) throw Error('Revision receipt capacity reached; reload the workspace');
    22	      const operations = input.edits.map(edit => edit.variants
    23	        ? { method: 'variant-store' as const, nodeId: edit.nodeId, expectedRevisionId: edit.baseRevisionId, variants: edit.variants }
    24	        : { method: 'diagram-revision-apply' as const, nodeId: edit.nodeId, expectedRevisionId: edit.baseRevisionId, revision: edit.revision });
    25	      const result = controller.applyUpdate(input.expectedVersion, [...operations, ...generatedDiagramOperations(input.creations)]);
    26	      const document = controller.getSnapshot().document;
    27	      const unresolvedEdgeIds = document.edges.filter(edge => {
    28	        try { validateConnectionAnchor(document.scene, edge.source); validateConnectionAnchor(document.scene, edge.target); return false; }
    29	        catch { return true; }
    30	      }).map(edge => edge.id);
    31	      receipt = { signature, result: { version: result.version, unresolvedEdgeIds } };
    32	      this.receipts.set(key, receipt);
    33	    }
    34	    if (!receipt.pending) {
    35	      const current = receipt;
    36	      current.pending = Promise.resolve().then(persist).then(() => current.result).catch(error => {
    37	        throw Error(`PERSISTENCE_PENDING: revision applied; retry the same request to flush: ${String(error)}`);
    38	      }).finally(() => { current.pending = undefined; });
    39	    }
    40	    return receipt.pending!;
    41	  }
    42	}
